def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    threatening_bids = []
    active_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid > 0:
                    active_count += 1
                    threatening_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threatening_bids) if threatening_bids else 0.0
    avg_threat = sum(threatening_bids) / len(threatening_bids) if threatening_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    survival_urgency = 0.0
    if hp <= 2:
        survival_urgency += 1.0
    elif hp <= 4:
        survival_urgency += 0.6
    elif hp <= 6:
        survival_urgency += 0.25

    if no_water_days >= 2:
        survival_urgency += 1.0
    elif no_water_days >= 1:
        survival_urgency += 0.45

    if day >= 8:
        survival_urgency += 0.2

    if active_count <= 1:
        base_bid = 24.0 + 18.0 * scarcity
    else:
        base_bid = 30.0 + 26.0 * scarcity

    if highest_threat >= 120:
        pressure_bid = 60.0 + 20.0 * scarcity
    elif highest_threat >= 70:
        pressure_bid = highest_threat + 3.0
    elif highest_threat > 0:
        pressure_bid = max(base_bid, avg_threat + 4.0)
    else:
        pressure_bid = base_bid

    bid = max(base_bid, pressure_bid)

    if survival_urgency >= 1.5:
        bid = max(bid, highest_prev + 6.0 if highest_prev > 0 else 90.0)
    elif survival_urgency >= 0.8:
        bid = max(bid, highest_threat + 4.0 if highest_threat > 0 else 65.0)
    elif survival_urgency >= 0.3:
        bid = max(bid, 52.0 + 10.0 * scarcity)

    if supply >= 23 and survival_urgency < 0.8:
        bid *= 0.82
    elif supply <= 17:
        bid *= 1.12

    reserve_target = DAILY_SALARY * max(0, 10 - day)
    soft_cap = budget
    if budget > reserve_target:
        soft_cap = min(budget, budget - (reserve_target * 0.15))

    if hp <= 2 or no_water_days >= 2:
        soft_cap = budget

    bid = min(bid, soft_cap)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    # Only one agent can get their full water requirement (13 units) given supply_range [15, 25].
    # This means direct competition for the single water slot.

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    # Base bid, adjusted by my health
    my_bid = DAILY_SALARY * 0.5 
    if my_status['no_water_days'] > 0 or my_status['hp'] <= 3:
        my_bid = DAILY_SALARY * 0.95 
    elif my_status['hp'] <= 5:
        my_bid = DAILY_SALARY * 0.8 

    # --- Opponent Analysis --- 
    alex_prev_bid = 0.0
    eric_prev_bid = 0.0
    alex_is_alive = False
    eric_is_alive = False

    for agent_id, opp in opponents_status.items():
        if opp['alive']:
            prev_trace = opp.get('previous_trace', {})
            if agent_id == "Alex":
                alex_is_alive = True
                if prev_trace and prev_trace.get('bid') is not None:
                    alex_prev_bid = prev_trace['bid']
                else:
                    # Default if no trace, based on meta-round context
                    alex_prev_bid = DAILY_SALARY * 0.85 
            elif agent_id == "Eric":
                eric_is_alive = True
                if prev_trace and prev_trace.get('bid') is not None:
                    eric_prev_bid = prev_trace['bid']
                else:
                    # Default if no trace, based on meta-round context
                    eric_prev_bid = DAILY_SALARY * 0.35 

    # Determine the target bid to beat for the single water slot
    target_bid_to_beat = 0.0

    if alex_is_alive:
        # Alex is the primary competitor. We need to beat Alex.
        target_bid_to_beat = alex_prev_bid
    elif eric_is_alive:
        # If Alex is not alive, Eric is the next competitor.
        target_bid_to_beat = eric_prev_bid

    # Adjust my bid to slightly exceed the target, if a target exists
    if target_bid_to_beat > 0:
        my_bid = max(my_bid, target_bid_to_beat + 1.0)

    # Ensure bid does not exceed budget
    my_bid = min(my_status['budget'], my_bid)

    # Ensure bid is at least 1.0 to win if uncontested
    my_bid = max(1.0, my_bid)

    return my_bid

